# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import gap_labels
from hourglass.errors import ProjectError

OPEN = parse_span("09:00-17:00")

def parse_all(texts):
    return [parse_span(text) for text in texts]

class GapLabelTests(unittest.TestCase):
    def check_gaps(self, texts, expected):
        worked = parse_all(texts)
        self.assertEqual(gap_labels(worked, OPEN), expected)

    def test_gap_between_shifts(self):
        self.check_gaps(
            ["09:00-12:00", "13:00-17:00"],
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_working_is_one_gap(self):
        self.check_gaps([], ["gap 09:00-17:00 (480 min)"])

    def test_fully_covered_has_no_gaps(self):
        self.check_gaps(["09:00-17:00"], [])

    def test_gaps_at_both_ends(self):
        self.check_gaps(
            ["10:00-16:00"],
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:00-17:00 (60 min)"
            ]
        )

    def test_overlaps_do_not_split_a_gap(self):
        self.check_gaps(
            ["09:00-12:00", "11:00-13:00", "14:00-17:00"],
            ["gap 13:00-14:00 (60 min)"]
        )

    def test_touching_shifts_leave_no_gap(self):
        self.check_gaps(["09:00-12:00", "12:00-17:00"], [])

    def test_order_of_shifts_does_not_matter(self):
        self.check_gaps(
            ["14:00-17:00", "09:00-12:00"],
            ["gap 12:00-14:00 (120 min)"]
        )

    def test_shift_before_opening_raises(self):
        with self.assertRaises(ProjectError):
            gap_labels(parse_all(["08:30-10:00"]), OPEN)

    def test_shift_after_closing_raises(self):
        with self.assertRaises(ProjectError):
            gap_labels(parse_all(["16:00-17:30"]), OPEN)
